using MagasinGestion.Data;

namespace MagasinGestion.Services;

public sealed class ProductService(SqliteConnectionFactory factory)
{
    public long Create(string reference, string name, long? categoryId, decimal salePrice, decimal threshold, long? userId, decimal initialStock = 0)
    { if(string.IsNullOrWhiteSpace(reference)||string.IsNullOrWhiteSpace(name)) throw new ArgumentException("Référence et nom obligatoires."); using var db=factory.Create(); using var tx=db.BeginTransaction(); using var c=db.CreateCommand(); c.Transaction=tx; c.CommandText="INSERT INTO Produit(CategorieId,Reference,Nom,PrixVente,StockMinimum) VALUES($c,$r,$n,$p,$s); SELECT last_insert_rowid();"; c.Parameters.AddWithValue("$c",(object?)categoryId??DBNull.Value); c.Parameters.AddWithValue("$r",reference.Trim()); c.Parameters.AddWithValue("$n",name.Trim()); c.Parameters.AddWithValue("$p",salePrice); c.Parameters.AddWithValue("$s",threshold); long id; try{id=Convert.ToInt64(c.ExecuteScalar());}catch(Exception ex) when(ex.Message.Contains("UNIQUE",StringComparison.OrdinalIgnoreCase)){throw new InvalidOperationException("Cette référence est déjà utilisée.",ex);} if(initialStock>0){using var m=db.CreateCommand();m.Transaction=tx;m.CommandText="INSERT INTO MouvementStock(ProduitId,Type,Quantite,StockAvant,StockApres,Motif,DateMouvement,Origine) VALUES($i,'Stock initial',$q,0,$q,'Création du produit',$d,'Stock initial')";m.Parameters.AddWithValue("$i",id);m.Parameters.AddWithValue("$q",initialStock);m.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));m.ExecuteNonQuery();} tx.Commit(); return id; }
    public void Archive(long id, long? userId) { using var db=factory.Create(); using var tx=db.BeginTransaction(); using var c=db.CreateCommand();c.Transaction=tx;c.CommandText="UPDATE Produit SET Actif=0 WHERE Id=$i";c.Parameters.AddWithValue("$i",id);c.ExecuteNonQuery(); using var a=db.CreateCommand();a.Transaction=tx;a.CommandText="INSERT INTO JournalAudit(UtilisateurId,Action,Entite,EntiteId,Details,DateAction) VALUES($u,'Archivage','Produit',$i,'Produit archivé',$d)";a.Parameters.AddWithValue("$u",(object?)userId??DBNull.Value);a.Parameters.AddWithValue("$i",id);a.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));a.ExecuteNonQuery();tx.Commit(); }
}
